class BinarySearchTree:
    def __init__(self):
        self.root_node = None

    def insert(self, key):
        def _rec_insert(curr, key):
            if not curr:
                return TreeNode(key)
            if key < curr.key:
                curr.left_child = _rec_insert(curr.left_child, key)
            elif key > curr.key:
                curr.right_child = _rec_insert(curr.right_child, key)
            return curr
        self.root_node = _rec_insert(self.root_node, key)

    def search(self, key):
        curr = self.root_node
        while curr and curr.key != key:
            curr = curr.left_child if key < curr.key else curr.right_child
        return curr is not None

    def in_order(self):
        res, stack = [], []
        curr = self.root_node
        while curr or stack:
            while curr:
                stack.append(curr)
                curr = curr.left_child
            curr = stack.pop()
            res.append(curr.key)
            curr = curr.right_child
        return res

